import React, { useEffect, useState } from 'react';
import { getCar } from '../services/carService';
import { getImageUrl } from '../services/api';
import { motion } from 'framer-motion';
import styles from './ComparePage.module.css';

const ComparePage = () => {
  const [cars, setCars] = useState([]);
  const [loading, setLoading] = useState(true);
  const [removedIds, setRemovedIds] = useState([]);

  useEffect(() => {
    const compareIds = JSON.parse(localStorage.getItem('compareList') || '[]');
    if (compareIds.length === 0) {
      setLoading(false);
      return;
    }

    const fetchCars = async () => {
      const loadedCars = [];
      const invalidIds = [];

      for (const id of compareIds) {
        try {
          const res = await getCar(id);
          loadedCars.push(res.data);
        } catch (err) {
          // Автомобиль не найден или другая ошибка – запоминаем id
          invalidIds.push(id);
        }
      }

      // Если были невалидные id, убираем их из localStorage
      if (invalidIds.length > 0) {
        const newList = compareIds.filter(id => !invalidIds.includes(id));
        localStorage.setItem('compareList', JSON.stringify(newList));
        setRemovedIds(invalidIds);
      }

      setCars(loadedCars);
      setLoading(false);
    };
    fetchCars();
  }, []);

  const clearCompare = () => {
    localStorage.removeItem('compareList');
    window.location.reload();
  };

  // Удаление одного автомобиля из сравнения
  const removeCar = (carId) => {
    const updatedIds = JSON.parse(localStorage.getItem('compareList') || '[]').filter(id => id !== carId);
    localStorage.setItem('compareList', JSON.stringify(updatedIds));
    setCars(prev => prev.filter(car => car.id !== carId));
  };

  if (loading) return <div className={styles.loading}>Загрузка...</div>;

  const currentIds = JSON.parse(localStorage.getItem('compareList') || '[]');
  if (cars.length === 0 && currentIds.length === 0) {
    return (
      <div className={styles.empty}>
        Нет автомобилей для сравнения. Добавьте их из каталога.
      </div>
    );
  }

  const attributes = [
    { key: 'image_url', label: 'Фото' },
    { key: 'brand', label: 'Марка' },
    { key: 'model', label: 'Модель' },
    { key: 'year', label: 'Год' },
    { key: 'price', label: 'Цена' },
    { key: 'body_type', label: 'Кузов' },
    { key: 'restyling', label: 'Рестайлинг' },
    { key: 'description', label: 'Описание' },
  ];

  return (
    <motion.div className={styles.page} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      {removedIds.length > 0 && (
        <div className={styles.warning}>
          Некоторые автомобили были удалены из каталога и исключены из сравнения.
        </div>
      )}

      <div className={styles.header}>
        <h1 className={styles.title}>Сравнение автомобилей</h1>
        <button className={styles.clearBtn} onClick={clearCompare}>Очистить список</button>
      </div>

      <div className={styles.tableWrapper}>
        <table className={styles.table}>
          <thead>
            <tr>
              <th>Характеристика</th>
              {cars.map(car => (
                <th key={car.id} className={styles.carHeader}>
                  {car.brand} {car.model}
                  <button
                    className={styles.removeCarBtn}
                    onClick={() => removeCar(car.id)}
                    title="Убрать из сравнения"
                  >
                    ×
                  </button>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {attributes.map(attr => (
              <tr key={attr.key}>
                <td className={styles.attrName}>{attr.label}</td>
                {cars.map(car => (
                  <td key={car.id} className={styles.attrValue}>
                    {attr.key === 'image_url' ? (
                      <img src={getImageUrl(car.image_url)} alt={car.model} className={styles.carImage} />
                    ) : attr.key === 'price' ? (
                      `${car.price.toLocaleString()} ₽`
                    ) : attr.key === 'restyling' ? (
                      car.restyling ? 'Да' : 'Нет'
                    ) : (
                      car[attr.key]
                    )}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </motion.div>
  );
};

export default ComparePage;
